# ---------------- writer + verifier ----------------
assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
os.makedirs(BASE, exist_ok=True)
sizes = {}
for cid in IDS:
    d = P[cid]
    obj = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    sizes[cid] = os.path.getsize(path)

# read-back verification (exact id list only, no glob)
ok = 0
for cid in IDS:
    path = os.path.join(BASE, cid + ".json")
    o = json.load(open(path, encoding="utf-8"))
    assert o["case_id"] == cid
    assert set(o.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, o.keys()
    assert isinstance(o["confidence"], float) and 0.0 <= o["confidence"] <= 1.0
    t = o["trigger"]
    assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed"))
    assert o["basis"].splitlines()[0].startswith("卡面 tradition＝liuyao")
    assert "systems_used" in o["basis"]
    ok += 1
print("VERIFIED", ok)
cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
print("TRIGGER changed_main=%d reserve_used=%d disputed=%d" % (cm, ru, di))
for cid in IDS:
    print(cid, sizes[cid])
